insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g8_science_v1'
from (values
('112.28.b.6.A',2,'A mixture that has the same composition throughout, such as salt dissolved in water, is...','["homogeneous", "an element", "a pure compound", "heterogeneous"]'::jsonb,0,'Uniform throughout means homogeneous.','original'),
('112.28.b.6.A',3,'Which is a heterogeneous mixture?','["sugar water", "a bowl of trail mix", "air in a sealed jar", "a bar of pure gold"]'::jsonb,1,'The parts of trail mix can be seen and separated.','original'),
('112.28.b.6.A',3,'Which is a pure substance that is a compound?','["orange juice with pulp", "air", "water", "salad"]'::jsonb,2,'Water is a pure substance made of two elements bonded.','original'),
('112.28.b.6.A',3,'A sample contains only one kind of atom. It is...','["a solution", "a heterogeneous mixture", "a compound", "an element"]'::jsonb,3,'Elements contain just one type of atom.','original'),
('112.28.b.6.A',4,'A student models a substance as two different kinds of atoms bonded in a fixed ratio. What is it?','["a compound", "a mixture", "an element", "a solution"]'::jsonb,0,'Fixed-ratio bonded atoms of different elements form a compound.','original'),
('112.28.b.6.A',4,'Which of these is a homogeneous mixture?','["granite", "vinegar", "pizza", "a pile of sand and iron filings"]'::jsonb,1,'Vinegar looks the same throughout.','original'),
('112.28.b.6.A',4,'How does a mixture differ from a compound?','["a compound can be separated by filtering", "a mixture is a pure substance", "the parts of a mixture are not chemically bonded", "a mixture always has a fixed formula"]'::jsonb,2,'Mixtures keep the properties of their parts.','original'),
('112.28.b.6.B',2,'Elements on the periodic table are arranged by increasing...','["state of matter at room temperature", "density", "color", "atomic number"]'::jsonb,3,'Atomic number is the number of protons.','original'),
('112.28.b.6.B',3,'In the reaction 2H2 + O2 -> 2H2O, which elements are the reactants made of?','["hydrogen and oxygen", "helium and oxygen", "nitrogen and oxygen", "hydrogen and carbon"]'::jsonb,0,'H is hydrogen and O is oxygen.','original'),
('112.28.b.6.B',3,'Which group on the periodic table contains elements that rarely react?','["alkali metals", "noble gases", "alkaline earth metals", "halogens"]'::jsonb,1,'Their outer shells are full.','original'),
('112.28.b.6.B',3,'Sodium (Na) and chlorine (Cl) react to form NaCl. Which tool tells you what the symbols stand for?','["a barometer", "a microscope", "the periodic table", "a spring scale"]'::jsonb,2,'It lists each element and its symbol.','original'),
('112.28.b.6.B',4,'In the reaction CH4 + 2O2 -> CO2 + 2H2O, which atoms are involved?','["hydrogen and nitrogen only", "carbon and nitrogen", "carbon and sulfur", "carbon, hydrogen and oxygen"]'::jsonb,3,'The symbols C, H and O appear.','original'),
('112.28.b.6.B',4,'Elements in the same column of the periodic table tend to have...','["similar chemical properties", "the same color", "identical masses", "the same number of protons"]'::jsonb,0,'They have the same number of outer electrons.','original'),
('112.28.b.6.B',4,'In the periodic table, metals are generally found...','["only in one column", "on the left and center", "on the far right", "only at the top"]'::jsonb,1,'Nonmetals are on the right.','original'),
('112.28.b.6.C',2,'Water molecules sticking to each other is called...','["condensation", "adhesion", "cohesion", "evaporation"]'::jsonb,2,'Cohesion is attraction between like molecules.','original'),
('112.28.b.6.C',2,'Water molecules sticking to other surfaces, like glass, is called...','["melting", "diffusion", "cohesion", "adhesion"]'::jsonb,3,'Adhesion is attraction between unlike substances.','original'),
('112.28.b.6.C',3,'Why do small drops of water form beads on a waxy leaf?','["cohesion pulls water molecules together", "water is repelled by gravity", "wax melts the water", "the leaf adds salt"]'::jsonb,0,'Cohesion and surface tension hold the drop together.','original'),
('112.28.b.6.C',3,'A water strider can walk on water because of...','["low density of the strider only", "surface tension", "evaporation", "gravity"]'::jsonb,1,'The surface behaves like a thin skin.','original'),
('112.28.b.6.C',4,'Water travels up through plant roots, stems and leaves partly because of...','["the Moon", "wind pushing it", "cohesion and adhesion", "gravity pulling it up"]'::jsonb,2,'Water sticks to itself and to the vessel walls.','original'),
('112.28.b.6.C',4,'A paper towel soaks up spilled water because water molecules...','["repel the fibers", "evaporate instantly", "turn into gas", "adhere to the fibers and pull other molecules along"]'::jsonb,3,'Adhesion plus cohesion draws water upward.','original'),
('112.28.b.6.C',4,'Which observation is caused by surface tension?','["a drop of water forming a rounded dome on a coin", "ice floating on water", "salt dissolving", "water boiling"]'::jsonb,0,'Surface tension pulls the surface into a tight shape.','original'),
('112.28.b.6.D',2,'A solution with a pH of 2 is...','["neutral", "an acid", "a base", "pure water"]'::jsonb,1,'pH below 7 is acidic.','original'),
('112.28.b.6.D',2,'Pure water has a pH of about...','["14", "1", "7", "10"]'::jsonb,2,'Pure water is neutral.','original'),
('112.28.b.6.D',3,'Which pH value is most basic?','["9", "3", "7", "13"]'::jsonb,3,'Higher pH means a stronger base.','original'),
('112.28.b.6.D',3,'Which property is common to bases?','["they feel slippery", "they turn blue litmus red", "they have a pH below 7", "they taste sweet"]'::jsonb,0,'Bases feel slippery (like soap).','original'),
('112.28.b.6.D',4,'Lemon juice has a pH of 2 and baking soda solution has a pH of 9. Which statement is correct?','["both are acids", "lemon juice is more acidic than water, and the baking soda solution is basic", "lemon juice is a base", "both are bases"]'::jsonb,1,'Below 7 is acid, above 7 is base.','original'),
('112.28.b.6.D',4,'What happens to pH when a base is added to an acid?','["the pH becomes 0", "the pH stays exactly the same", "the pH rises toward 7", "the pH falls"]'::jsonb,2,'Neutralization moves toward neutral.','original'),
('112.28.b.6.D',4,'How many times more acidic is a solution of pH 3 than one of pH 4?','["3 times", "100 times", "2 times", "10 times"]'::jsonb,3,'Each pH step is a factor of 10.','original'),
('112.28.b.6.E',2,'The law of conservation of mass says that in a chemical reaction, mass is...','["neither created nor destroyed", "always lost", "turned into energy only", "always gained"]'::jsonb,0,'Total mass stays the same.','original'),
('112.28.b.6.E',3,'10 g of reactant A reacts completely with 15 g of reactant B. What is the total mass of the products?','["10 g", "25 g", "150 g", "5 g"]'::jsonb,1,'Mass of products equals mass of reactants.','original'),
('112.28.b.6.E',3,'A chemical equation is balanced when...','["the reactants are heavier", "the arrows are equal", "each type of atom has the same count on both sides", "the products are fewer"]'::jsonb,2,'Atoms are only rearranged.','original'),
('112.28.b.6.E',4,'Is the equation 2H2 + O2 -> 2H2O balanced?','["no, there are more H on the right", "yes, but only the O is balanced", "no, there are more O on the right", "yes, 4 H and 2 O on each side"]'::jsonb,3,'Count: 4 H and 2 O on both sides.','original'),
('112.28.b.6.E',4,'Is the equation H2 + O2 -> H2O balanced?','["no, there are 2 O on the left and 1 on the right", "no, hydrogen is missing", "yes", "no, there are more H on the right"]'::jsonb,0,'Oxygen atoms are not equal.','original'),
('112.28.b.6.E',4,'A student burns a candle in an open room and the candle seems to lose mass. Where did the mass go?','["it was destroyed", "into gases like carbon dioxide and water vapor released into the air", "it stayed in the wick", "it turned into energy only"]'::jsonb,1,'Mass is conserved when all products are counted.','original'),
('112.28.b.6.E',4,'Balance: N2 + __H2 -> 2NH3. What number goes in the blank?','["6", "1", "3", "2"]'::jsonb,2,'6 H atoms are needed on the right so 3 H2.','original'),
('112.28.b.7.A',2,'Newton''s Second Law can be written as...','["m = F x a", "a = F x m", "F = m / a", "F = m x a"]'::jsonb,3,'Force equals mass times acceleration.','original'),
('112.28.b.7.A',3,'A 2 kg cart is pushed with a net force of 10 N. What is its acceleration?','["5 m/s2", "20 m/s2", "12 m/s2", "0.2 m/s2"]'::jsonb,0,'a = F / m = 10 / 2.','original'),
('112.28.b.7.A',3,'If the net force on an object is made twice as large and the mass stays the same, the acceleration...','["stays the same", "doubles", "halves", "becomes zero"]'::jsonb,1,'Acceleration is proportional to force.','original'),
('112.28.b.7.A',3,'If the mass of an object doubles and the force stays the same, the acceleration...','["stays the same", "doubles", "is cut in half", "quadruples"]'::jsonb,2,'Acceleration is inversely related to mass.','original'),
('112.28.b.7.A',4,'What net force gives a 4 kg object an acceleration of 3 m/s2?','["7 N", "1.3 N", "0.75 N", "12 N"]'::jsonb,3,'F = 4 x 3.','original'),
('112.28.b.7.A',4,'A 1,000 kg car accelerates at 2 m/s2. What is the net force on the car?','["2,000 N", "998 N", "1,002 N", "500 N"]'::jsonb,0,'F = 1000 x 2.','original'),
('112.28.b.7.A',4,'Two carts get the same push. Cart A has a mass of 1 kg and Cart B has a mass of 3 kg. Which accelerates more?','["neither accelerates", "the lighter cart", "they accelerate equally", "the heavier cart"]'::jsonb,1,'Less mass means more acceleration.','original'),
('112.28.b.7.B',3,'A seat belt keeps a passenger in place during a sudden stop. This mostly demonstrates Newton''s...','["Third Law", "Law of Gravitation", "First Law", "Second Law"]'::jsonb,2,'The passenger''s body tends to keep moving.','original'),
('112.28.b.7.B',3,'A swimmer pushes water backward and moves forward. This demonstrates Newton''s...','["First Law", "Second Law", "Law of Conservation of Mass", "Third Law"]'::jsonb,3,'Action and reaction forces.','original'),
('112.28.b.7.B',3,'A bigger force on a shopping cart makes it speed up more. This demonstrates Newton''s...','["Second Law", "First Law", "Third Law", "Law of Gravity"]'::jsonb,0,'More force gives more acceleration.','original'),
('112.28.b.7.B',4,'A car hits a wall. Which laws help explain why an unrestrained passenger is injured?','["none of the laws", "First Law (inertia) and Second Law (large force over a short time)", "only the Third Law", "only the Law of Gravity"]'::jsonb,1,'Inertia keeps the passenger moving; stopping quickly takes a large force.','original'),
('112.28.b.7.B',4,'On a roller coaster, riders feel pressed into their seats on a sharp turn. Which idea explains this?','["friction speeds them up", "gravity turns off", "inertia: their bodies tend to keep moving in a straight line", "the seat creates mass"]'::jsonb,2,'The seat pushes inward to change their direction.','original'),
('112.28.b.7.B',4,'A football player tackles another. Which statement is correct?','["only the tackler exerts force", "the lighter player exerts more force", "forces cancel and neither moves", "each player exerts an equal and opposite force on the other"]'::jsonb,3,'Third Law pairs are equal and opposite.','original'),
('112.28.b.7.B',4,'Airbags in cars reduce injury by...','["increasing the time over which the passenger stops, so the force is smaller", "increasing the speed of the car", "decreasing the passenger''s mass", "removing inertia"]'::jsonb,0,'Same change in motion over longer time means less force.','original'),
('112.28.b.8.A',3,'The height of a wave from its rest position to its crest is its...','["wavelength", "amplitude", "speed", "frequency"]'::jsonb,1,'Greater amplitude means more energy.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Science' and d.language = 'en'
on conflict (fingerprint) do nothing;
