from (values
('112.28.b.8.A',3,'Frequency is the number of waves that pass a point per...','["kilogram", "meter", "second", "degree"]'::jsonb,2,'Measured in hertz.','original'),
('112.28.b.8.A',3,'Which electromagnetic wave has the longest wavelength?','["X-rays", "gamma rays", "ultraviolet", "radio waves"]'::jsonb,3,'Radio waves are at the long-wavelength end.','original'),
('112.28.b.8.A',4,'As the frequency of an electromagnetic wave increases, its wavelength...','["decreases", "doubles", "stays the same", "increases"]'::jsonb,0,'In a given medium, wavelength and frequency are inversely related.','original'),
('112.28.b.8.A',4,'Which has the highest frequency?','["visible light", "gamma rays", "radio waves", "microwaves"]'::jsonb,1,'Gamma rays are at the high-energy end.','original'),
('112.28.b.8.A',4,'Which color of visible light has the shortest wavelength?','["yellow", "red", "violet", "green"]'::jsonb,2,'Violet is at the short end.','original'),
('112.28.b.8.B',3,'Which type of electromagnetic wave is used in radiation therapy to kill cancer cells?','["sound waves", "radio waves", "visible light only", "gamma rays or X-rays"]'::jsonb,3,'High-energy rays can damage cells.','original'),
('112.28.b.8.B',3,'Microwave ovens heat food using...','["microwaves", "gamma rays", "X-rays", "sound waves"]'::jsonb,0,'Microwaves make water molecules vibrate.','original'),
('112.28.b.8.B',3,'Wi-Fi and cell phones send information using...','["ultraviolet rays", "radio waves and microwaves", "X-rays", "gamma rays"]'::jsonb,1,'These waves carry signals without wires.','original'),
('112.28.b.8.B',4,'Fiber optic cables transmit information using...','["sound waves", "magnetism", "pulses of light", "heat only"]'::jsonb,2,'Light bounces along glass strands.','original'),
('112.28.b.8.B',4,'Ultraviolet light is used to sterilize equipment because it...','["adds oxygen", "creates heat only", "makes metal softer", "can damage the DNA of germs"]'::jsonb,3,'UV breaks down microbes.','original'),
('112.28.b.8.B',4,'Why should people wear sunscreen?','["to protect skin from harmful ultraviolet rays", "to block radio waves", "to block sound", "to stop gravity"]'::jsonb,0,'UV can cause sunburn and skin damage.','original'),
('112.28.b.8.B',4,'A doctor uses X-rays to see a broken bone because X-rays...','["are absorbed by all tissue equally", "pass through soft tissue but are absorbed by bone", "are sound waves", "pass through bone but not skin"]'::jsonb,1,'Bone absorbs more.','original'),
('112.28.b.9.A',2,'Stars form from clouds of gas and dust called...','["planets", "comets", "nebulae", "asteroids"]'::jsonb,2,'Gravity pulls the nebula together.','original'),
('112.28.b.9.A',3,'What happens when a star the size of our Sun runs out of fuel?','["it becomes a black hole", "it explodes as a supernova", "it turns into a planet", "it becomes a red giant, then a white dwarf"]'::jsonb,3,'Medium-mass stars end as white dwarfs.','original'),
('112.28.b.9.A',3,'A very massive star ends its life as a(n)...','["supernova", "nebula", "white dwarf only", "comet"]'::jsonb,0,'It explodes and may leave a neutron star or black hole.','original'),
('112.28.b.9.A',4,'On the Hertzsprung-Russell diagram, most stars (like the Sun) fall in the...','["supergiant region", "main sequence", "white dwarf region", "giant region"]'::jsonb,1,'A diagonal band includes most stars.','original'),
('112.28.b.9.A',4,'On an H-R diagram, which stars are hot but dim?','["main sequence stars", "supergiants", "white dwarfs", "red giants"]'::jsonb,2,'They are small, so dim despite high temperature.','original'),
('112.28.b.9.A',4,'A star is cool but very bright. On the H-R diagram it is most likely a...','["white dwarf", "main sequence dwarf", "neutron star", "red giant or supergiant"]'::jsonb,3,'Large surface area makes it bright.','original'),
('112.28.b.9.A',4,'The Sun produces energy by...','["fusing hydrogen into helium", "splitting uranium", "chemical reactions", "burning coal"]'::jsonb,0,'Nuclear fusion releases energy.','original'),
('112.28.b.9.B',2,'Our solar system is located in the...','["Orion Nebula", "Milky Way galaxy", "Andromeda galaxy", "Large Magellanic Cloud"]'::jsonb,1,'The Milky Way is our home galaxy.','original'),
('112.28.b.9.B',3,'A galaxy with arms that wind around a bright center is a...','["dwarf star", "elliptical galaxy", "spiral galaxy", "irregular galaxy"]'::jsonb,2,'Spiral galaxies have arms.','original'),
('112.28.b.9.B',3,'A galaxy shaped like a smooth oval with no clear arms is...','["barred only", "spiral", "irregular", "elliptical"]'::jsonb,3,'Smooth shape means elliptical.','original'),
('112.28.b.9.B',3,'A galaxy with no regular shape is...','["irregular", "elliptical", "spiral", "a nebula"]'::jsonb,0,'Irregular galaxies lack a defined structure.','original'),
('112.28.b.9.B',4,'The Milky Way is classified as a...','["nebula", "spiral galaxy", "elliptical galaxy", "irregular galaxy"]'::jsonb,1,'It has spiral arms.','original'),
('112.28.b.9.B',4,'Where is our solar system located in the Milky Way?','["at the exact center", "outside the galaxy", "in one of the spiral arms, far from the center", "in a separate cluster"]'::jsonb,2,'We are in the Orion Arm region.','original'),
('112.28.b.9.B',4,'Galaxies are held together by...','["wind", "friction", "magnetism", "gravity"]'::jsonb,3,'Gravity binds stars and gas.','original'),
('112.28.b.9.C',2,'Which theory describes the origin of the universe from a hot, dense beginning?','["the Big Bang theory", "the germ theory", "the plate tectonics theory", "the cell theory"]'::jsonb,0,'The universe has been expanding since.','original'),
('112.28.b.9.C',3,'Galaxies are moving away from each other. This is evidence that the universe is...','["shrinking", "expanding", "made of ice", "standing still"]'::jsonb,1,'Redshift shows galaxies receding.','original'),
('112.28.b.9.C',3,'Light from distant galaxies is shifted toward the red end of the spectrum. This is called...','["reflection", "refraction only", "redshift", "blueshift"]'::jsonb,2,'It shows the galaxies move away.','original'),
('112.28.b.9.C',4,'Cosmic microwave background radiation is evidence for...','["evolution", "climate change", "plate tectonics", "the early hot universe after the Big Bang"]'::jsonb,3,'It is leftover radiation from early times.','original'),
('112.28.b.9.C',4,'Why do scientists look at light from distant galaxies to study the early universe?','["light takes a long time to travel, so we see the galaxy as it was long ago", "light never travels", "light speeds up with distance", "galaxies make no light"]'::jsonb,0,'Looking far away is looking back in time.','original'),
('112.28.b.9.C',4,'A scientific theory is best described as...','["a law that never changes", "an explanation supported by a large body of evidence", "a guess", "an opinion"]'::jsonb,1,'Theories are tested and supported repeatedly.','original'),
('112.28.b.9.C',4,'Which evidence supports the Big Bang theory?','["tides", "the water cycle", "the observed expansion of the universe", "the existence of seasons"]'::jsonb,2,'Expansion implies a beginning.','original'),
('112.28.b.10.A',2,'What is the main energy source for Earth''s weather?','["the Moon", "ocean tides", "volcanoes", "the Sun"]'::jsonb,3,'The Sun heats the air and water unevenly.','original'),
('112.28.b.10.A',3,'Differences in heating between land and sea cause...','["winds", "tides", "volcanoes", "earthquakes"]'::jsonb,0,'Warm air rises and cooler air moves in.','original'),
('112.28.b.10.A',3,'Water evaporating from the ocean adds what to the atmosphere?','["salt", "water vapor", "ozone", "oxygen only"]'::jsonb,1,'Water vapor condenses into clouds.','original'),
('112.28.b.10.A',3,'Weather is the condition of the atmosphere over a short time. Climate is...','["tomorrow''s forecast", "the wind speed", "the average weather in a region over a long time", "the weather today"]'::jsonb,2,'Climate is long-term.','original'),
('112.28.b.10.A',4,'Which process transfers energy from the ocean to the atmosphere?','["erosion", "deposition", "sedimentation", "evaporation"]'::jsonb,3,'Evaporation carries energy in water vapor.','original'),
('112.28.b.10.A',4,'A region near the equator is warmer than one near the poles because...','["sunlight strikes more directly at the equator", "the poles have no atmosphere", "the equator is closer to the Moon", "the equator has more gravity"]'::jsonb,0,'Direct rays are more concentrated.','original'),
('112.28.b.10.B',2,'Winds are caused by differences in...','["mass", "air pressure", "salinity", "gravity"]'::jsonb,1,'Air flows from high to low pressure.','original'),
('112.28.b.10.B',3,'The Coriolis effect is caused by...','["ocean tides", "the Moon''s gravity", "Earth''s rotation", "solar flares"]'::jsonb,2,'It curves moving air and water.','original'),
('112.28.b.10.B',3,'In the Northern Hemisphere, the Coriolis effect deflects moving air to the...','["left", "down", "up", "right"]'::jsonb,3,'Winds curve clockwise-ish to the right.','original'),
('112.28.b.10.B',4,'Most of the United States is in a belt of winds that blow mostly from the west. They are called the...','["prevailing westerlies", "polar easterlies", "trade winds", "doldrums"]'::jsonb,0,'Weather systems usually move west to east.','original'),
('112.28.b.10.B',4,'Why do weather systems in Texas usually move from west to east?','["volcanoes", "prevailing westerly winds", "ocean tides", "the Moon''s pull"]'::jsonb,1,'The global wind belt pushes them east.','original'),
('112.28.b.10.B',4,'The jet stream is...','["a mountain wind", "an ocean current", "a fast current of air high in the atmosphere", "a type of cloud"]'::jsonb,2,'It steers weather systems.','original'),
('112.28.b.10.B',4,'Warm moist air rising at the equator is part of a global pattern called...','["erosion", "tides", "plate tectonics", "atmospheric circulation"]'::jsonb,3,'Heat drives the movement of air around Earth.','original'),
('112.28.b.10.C',2,'Hurricanes form over...','["warm ocean water", "deserts", "cold ocean water", "mountains"]'::jsonb,0,'They draw energy from warm water.','original'),
('112.28.b.10.C',3,'What sea surface temperature is generally needed for hurricanes to form?','["below 10 C", "above about 26 C (80 F)", "below freezing", "exactly 0 C"]'::jsonb,1,'Warm water supplies heat and moisture.','original'),
('112.28.b.10.C',3,'A hurricane weakens when it moves over land because it loses...','["its wind", "its gravity", "its supply of warm, moist ocean air", "its rotation direction"]'::jsonb,2,'Land cuts off the energy source.','original'),
('112.28.b.10.C',4,'In the Northern Hemisphere, a hurricane spins...','["straight", "up and down only", "clockwise", "counterclockwise"]'::jsonb,3,'Because of the Coriolis effect.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
